-- 640: Şehir listesi (Şehir Şampiyonu — arka plan, brif tasarim/BRIEF_SEHIR_SAMPIYONU.md A4.4)
--
-- * Şehir yalnız listeden seçilir: `sehirler` tablosu artık her ülke için dolu.
--   Türkiye: 81 il (resmi adlar, depodaki liste; "Hakkâri" → resmi yazım "Hakkari").
--   Diğer 84 ülke: GeoNames (CC BY 4.0) nüfusu 100.000+ şehirler; hiç 100.000+ şehri olmayan
--   ülkede (Lüksemburg) en kalabalık 3 şehir. Veri bölümü araclar/sehir-listesi/uret.mjs ile üretildi.
-- * `nufus` (arama sonucunda büyük şehir önce, bot dağılımı) ve `kaynak` ('resmi_il' | 'geonames').
-- * `sehir_anahtar(text)`: büyük/küçük harf, Türkçe ve Latin aksanlı harf, boşluk/noktalama farkını
--   siler — eski serbest kayıtları listeye eşlemek için.
-- * Eski kayıtlar listeye eşlenir; eşleşmeyen şehir boşaltılır (ülke kalır). Gizli botların
--   şehirleri geçerli listeden, nüfusa göre dağıtılır (en az taşıma ile).
-- Yetki/RLS değişikliği YOK (sehirler herkese okunur politikası aynen durur).

alter table public.sehirler add column if not exists nufus integer;
alter table public.sehirler add column if not exists kaynak text not null default 'resmi_il';

create or replace function public.sehir_anahtar(p text)
returns text
language sql
immutable
set search_path = public
as $$
  select nullif(regexp_replace(
    translate(lower(translate(coalesce(p, ''),
      'İIÇĞÖŞÜÂÎÛÉÈÊËÁÀÄÃÅÓÒÔÕØÚÙÑÍÌÏÝĆČŚŠŹŽŻŁŃŐŰŘŤĎĚ',
      'iıçğöşüâîûéèêëáàäãåóòôõøúùñíìïýćčśšźžżłńőűřťďě')),
      'çğıöşüâîûéèêëáàäãåóòôõøúùñíìïýćčśšźžżłńőűřťďěß',
      'cgiosuaiueeeeaaaaaooooouuniiiyccsszzzlnourtdes'),
    '[^a-z0-9]', '', 'g'), '');
$$;
comment on function public.sehir_anahtar(text) is
  '640: şehir adını karşılaştırma anahtarına çevirir (harf/aksan/boşluk farkı yok). Yalnız eşleme için.';

-- Hakkâri → Hakkari (valilik ve TÜİK yazımı). Bu ilde kayıtlı oyuncu/arşiv yok; yine de eşlenir.
update public.sehirler set ad = 'Hakkari' where ulke = 'TR' and ad = 'Hakkâri';
update public.profiles set sehir = 'Hakkari' where ulke = 'TR' and sehir = 'Hakkâri';

-- Bir gizli botun ülkesi (GH) listede yoktu → ülke listesine eklendi (şehirleri aşağıda).
insert into public.ulkeler (kod, ad) values ('GH', 'Gana') on conflict (kod) do nothing;

-- ÜRETİLDİ: araclar/sehir-listesi/uret.mjs — elle düzenleme yapma.
-- Kaynak: GeoNames (CC BY 4.0). 4875 yabancı şehir; 81 il nüfusu.
-- 100.000+ şehri olmayan ülkeler (en kalabalık 3): LU:3

