-- 81 il nüfusu (GeoNames ADM1; il adları depodaki listeden, eşleme anahtarla)
update public.sehirler s
   set nufus = n.nufus, kaynak = 'resmi_il'
  from _il_nufus n
 where s.ulke = 'TR' and public.sehir_anahtar(s.ad) = public.sehir_anahtar(n.ad);

do $$
begin
  if exists (select 1 from public.sehirler where ulke = 'TR' and nufus is null) then
    raise exception '640: nüfusu eşlenemeyen il var';
  end if;
  if exists (select 1 from public.ulkeler u where not exists (select 1 from public.sehirler s where s.ulke = u.kod)) then
    raise exception '640: şehir listesi boş ülke var';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Eski kayıtların eşlenmesi (insan + bot). Anahtar birebir eşleşmezse sondaki
-- "city / şehri / şehir" eki atılarak bir kez daha denenir (ör. "Cebu" → "Cebu City").
-- Eşleşmeyen şehir boşaltılır; ülke kalır (oyuncu şehirsiz sayılır, listeden seçer).
-- ---------------------------------------------------------------------------
with eslesme as (
  select p.id,
         (select s.ad
            from public.sehirler s
           where s.ulke = p.ulke
             and (public.sehir_anahtar(s.ad) = public.sehir_anahtar(p.sehir)
                  or regexp_replace(public.sehir_anahtar(s.ad), '(city|sehri|sehir)$', '')
                   = regexp_replace(public.sehir_anahtar(p.sehir), '(city|sehri|sehir)$', ''))
           order by (public.sehir_anahtar(s.ad) = public.sehir_anahtar(p.sehir)) desc, s.nufus desc nulls last
           limit 1) as yeni
    from public.profiles p
   where p.sehir is not null
)
update public.profiles p
   set sehir = e.yeni
  from eslesme e
 where e.id = p.id and p.sehir is distinct from e.yeni;

-- ---------------------------------------------------------------------------
-- Gizli botların Türkiye dağılımı: 81 ilin nüfus payına göre kota (en büyük kalan
-- yöntemi). Kotasının üstündeki il fazlası, kotası boş kalan illere taşınır; kotası
-- içindeki botların şehri DEĞİŞMEZ (en az taşıma). Açık botlar şehir listesinde
-- görünmediği için dokunulmaz.
-- ---------------------------------------------------------------------------
create temp table _bot_kota on commit drop as
with il as (select ad, nufus::numeric as nufus from public.sehirler where ulke = 'TR'),
     bot as (select count(*)::numeric as n from public.profiles p
              where coalesce(p.is_bot, false) and not public.acik_bot_mu(p.is_bot, p.bot_turu) and p.ulke = 'TR'),
     ham as (select il.ad, il.nufus, bot.n * il.nufus / sum(il.nufus) over () as pay from il, bot),
     taban as (select ad, nufus, floor(pay)::int as t, pay - floor(pay) as kalan from ham)
select ad, nufus,
       t + case when row_number() over (order by kalan desc, nufus desc)
                     <= (select n from bot)::int - (select sum(t) from taban)::int then 1 else 0 end as kota
  from taban;

with b as (
  select p.id, p.sehir,
         row_number() over (partition by p.sehir order by md5(p.id::text)) as rn
    from public.profiles p
   where coalesce(p.is_bot, false) and not public.acik_bot_mu(p.is_bot, p.bot_turu) and p.ulke = 'TR'
),
fazla as (
  select b.id, row_number() over (order by md5(b.id::text)) as sira
    from b left join _bot_kota k on k.ad = b.sehir
   where b.sehir is null or b.rn > coalesce(k.kota, 0)
),
mevcut as (select sehir, count(*)::int as n from b group by sehir),
bos as (
  select k.ad, row_number() over (order by k.nufus desc, k.ad, g) as sira
    from _bot_kota k
    left join mevcut m on m.sehir = k.ad
    cross join lateral generate_series(1, greatest(k.kota - coalesce(m.n, 0), 0)) g
)
update public.profiles p
   set sehir = bos.ad
  from fazla join bos on bos.sira = fazla.sira
 where p.id = fazla.id;

-- ---------------------------------------------------------------------------
-- Türkiye dışındaki gizli botlar (bugün hepsi şehirsiz): ülkesinin en kalabalık 10
-- şehrinden nüfus ağırlıklı, bot kimliğinden sabit seçim (büyük şehre daha çok bot).
-- ---------------------------------------------------------------------------
with aday as (
  select s.ulke, s.ad,
         sum(s.nufus) over (partition by s.ulke order by s.nufus desc, s.ad rows between unbounded preceding and current row)::numeric
         / nullif(sum(s.nufus) over (partition by s.ulke), 0) as ust
    from (select ulke, ad, coalesce(nufus, 0) as nufus,
                 row_number() over (partition by ulke order by nufus desc nulls last, ad) as r
            from public.sehirler where ulke <> 'TR') s
   where s.r <= 10
),
secim as (
  select p.id,
         (select a.ad from aday a
           where a.ulke = p.ulke
             and a.ust >= (('x' || substr(md5(p.id::text || ':sehir'), 1, 8))::bit(32)::bigint / 4294967296.0)
           order by a.ust
           limit 1) as ad
    from public.profiles p
   where coalesce(p.is_bot, false) and not public.acik_bot_mu(p.is_bot, p.bot_turu)
     and p.ulke is not null and p.ulke <> 'TR' and p.sehir is null
)
update public.profiles p
   set sehir = secim.ad
  from secim
 where secim.id = p.id and secim.ad is not null;
